  'צרו פוסט בסבב, בחרו קבוצות ותזמנו — כל פרסום יופיע כאן עם השעה שלו.': 'Создайте пост в цикле, выберите группы и запланируйте — каждая публикация появится здесь со своим временем.',
  'צרו פוסט, בחרו קבוצות ולחצו "התחל פרסום" — התור יופיע כאן בזמן אמת.': 'Создайте пост, выберите группы и нажмите «Начать публикацию» — очередь появится здесь в реальном времени.',
  'צרו פוסט, בחרו קבוצות ותזמנו — השעה של הפרסום הבא תופיע כאן.': 'Создайте пост, выберите группы и запланируйте — время следующей публикации появится здесь.',
  'צריך לאשר את המייל קודם — חפשו הודעה מאיתנו בתיבה (גם בספאם) ולחצו על הקישור שבה.': 'Сначала нужно подтвердить почту — найдите письмо от нас в ящике (в том числе в спаме) и нажмите на ссылку в нём.',
  'צריך להקליד מה לחפש — עיר, אזור או נושא.': 'Нужно ввести, что искать — город, район или тему.',
  'צריך להריץ את social-latest.sql ב-Supabase לפני שאפשר להוסיף תגובות. אפשר להריץ אותו שוב גם אם כבר הרצתם.': 'Нужно выполнить social-latest.sql в Supabase, прежде чем можно будет добавлять комментарии. Его можно выполнить снова, даже если вы уже выполняли.',
  'צריך להתחבר מחדש לפייסבוק': 'Нужно войти в Facebook заново',
  'קבוצה אחת הוסתרה — הצג אותה': 'Одна группа скрыта — показать её',
