  'קבוצה הוסרה מהתור': 'Группа убрана из очереди',
  'קבוצה נוספת נמצאת': 'Найдена ещё одна группа',
  'קבוצה שלא מאפשרת תדולג ותופיע ברשימה עם הסיבה — היא תישאר פעילה ותמשיך לעבוד מהפרופיל האישי.': 'Группа, которая не разрешает, будет пропущена и появится в списке с причиной — она останется активной и продолжит работать из личного профиля.',
  'קבוצה שלא מאפשרת תדולג ותישאר פעילה.': 'Группа, которая не разрешает, будет пропущена и останется активной.',
  'קבוצה שמבקשת לענות על שאלות הצטרפות — נדלג עליה ותענה בעצמך. אם פייסבוק יגביל, נעצור מיד.': 'Группу, которая просит ответить на вопросы при вступлении, мы пропустим, и вы ответите сами. Если Facebook ограничит, мы сразу остановимся.',
