  'קמפיין הוא המסגרת שמאגדת פוסטים לפי שירות ועיר — למשל "ניקוי ספות באר שבע". אחר כך מוסיפים לו פוסט ובוחרים קבוצות.': 'Кампания — это рамка, которая объединяет посты по услуге и городу — например «чистка диванов Беэр-Шева». Затем в неё добавляют пост и выбирают группы.',
