  'שום דבר לא ממתין לצאת. מה שכבר פורסם נשאר בהיסטוריה, והמונה יתחיל מאפס בפעם הבאה שתפרסמו את הפוסט הזה.': 'Ничего не ждёт выхода. То, что уже опубликовано, остаётся в истории, и счётчик начнётся с нуля в следующий раз, когда вы опубликуете этот пост.',
