  'תזמונים פעילים יבוטלו ופרסומים שטרם יצאו ידולגו. מה שכבר פורסם נשאר בהיסטוריה.': 'Активные расписания будут отменены, а ещё не вышедшие публикации пропущены. То, что уже опубликовано, остаётся в истории.',
  'תזמונים פעילים של הפוסט יבוטלו ופרסומים שטרם יצאו ידולגו. מה שכבר פורסם נשאר בהיסטוריה.': 'Активные расписания поста будут отменены, а ещё не вышедшие публикации пропущены. То, что уже опубликовано, остаётся в истории.',
  'תזמונים פעילים שלהם יבוטלו ופרסומים שטרם יצאו ידולגו. מה שכבר פורסם נשאר בהיסטוריה.': 'Их активные расписания будут отменены, а ещё не вышедшие публикации пропущены. То, что уже опубликовано, остаётся в истории.',
