  'תקלה זמנית בשרת. נסו שוב בעוד רגע.': 'Временный сбой на сервере. Попробуйте снова через мгновение.',
  'תקלה טכנית. הפרטים המלאים נשמרו ביומן במערכת.': 'Техническая неполадка. Полные подробности сохранены в журнале системы.',
  'תתחדש אוטומטית ב-': 'Возобновится автоматически в ',
  '— אפשר לבדוק אם נוספו קבוצות חדשות.': '— можно проверить, добавились ли новые группы.',
  '— היא תמשיך לעבוד כרגיל מהפרופיל האישי.': '— она продолжит работать как обычно из личного профиля.',
  '— חדדו את החיפוש כדי למצוא קבוצה מסוימת.': '— уточните поиск, чтобы найти конкретную группу.',
  '— לא ייצא עד שתמשיכו': '— не выйдет, пока вы не продолжите',
  '— לפי המרווח שהגדרתם. המרווח בין פרסומים עשוי לדחות פרסומים ולהאריך את הטווח; חריגה מהמכסות שהגדרתם בהגדרות נדחית ליום הראשון שיש בו מקום.': '— по интервалу, который вы задали. Интервал между публикациями может отложить публикации и растянуть диапазон; выход за квоты, заданные вами в настройках, откладывается на первый день, где есть место.',
  'הפתרון המבריק — ניהול פרסום': 'הפתרון המבריק — Управление публикациями',
  'הפתרון המבריק — פרסום': 'הפתרון המבריק — Публикации',
  'חזרה יומית הופעלה': 'Ежедневный повтор включён',
  'חזרה יומית כובתה': 'Ежедневный повтор отключён',
