  'חזרה יומית פעילה — הסבב הבא ייפתח לבד': 'Ежедневный повтор активен — следующий цикл откроется сам',
  'חזרה יומית פעילה — חלון הפרסום פתוח, הסבב הבא ייפתח בכל רגע': 'Ежедневный повтор активен — окно публикации открыто, следующий цикл откроется в любой момент',
  'חיפוש קבוצה להוספה לתור': 'Поиск группы для добавления в очередь',
