/*
 * THE ONLY ENTRIES ALLOWED TO HAVE NO CYRILLIC.
 *
 * worker/test/auth-screen.test.ts refuses a "translation" with no Cyrillic in
 * it, because that is what a Latin transliteration looks like — and a
 * transliteration is a bug that reads as done. A brand name is the honest
 * exception: Facebook is Facebook in Russian too. Each one is named here so
 * the exception is deliberate and visible, rather than the guard being
 * loosened for everybody.
 */
export const LATIN_OK: readonly string[] = ['פייסבוק'];

/* ─── sentences with a value inside them ─────────────────────────────────
 *
 * "התוכנה לא עוברת לרוסית מלאה … עדיין יש כפתורים והרבה דברים בעברית."
 *
 * A dictionary keyed by the whole sentence answers 1,919 of this app's
 * sentences and CANNOT answer the other 509, because those are not fixed
 * sentences at all — they are built around a value:
 *
 *     `הקבוצה "${name}" הוסרה מהתור`
 *     `הפרסום הבא ב-${time}`
 *
 * On screen that is ONE text node reading `הקבוצה "ניקוי ספות" הוסרה מהתור`,
 * and no fixed key will ever equal it. Translating the pieces around the
 * value instead (`" הוסרה מהתור"`) is worse than useless: Russian does not
 * put its words in Hebrew's order, so the pieces would land in the wrong
 * places and the sentence would come out scrambled.
 *
 * SO THE PATTERN IS THE KEY, with § standing where the value goes, and the
 * Russian puts its own § wherever Russian grammar needs it:
 *
 *     'הקבוצה "§" הוסרה מהתור': 'Группа "§" убрана из очереди'
 *     'נשארו § דקות':           'Осталось § минут'
 *
 * EVERY PATTERN IS ANCHORED AT BOTH ENDS when it is matched, so a pattern
 * describes the shape of a whole text node and cannot swallow a longer
 * sentence that merely contains it. worker/test/auth-screen.test.ts also
 * refuses a pattern whose § count differs between the two languages (the
 * value would be dropped on the floor) and one with too little literal text
 * to identify it.
 */
export const PH = '§';

/*
 * THE ONLY PATTERNS ALLOWED TO BE THIN.
 *
 * A pattern needs literal text to identify it; two Hebrew letters in a row
 * is the floor, and worker/test/auth-screen.test.ts enforces it. One shape
 * in this app genuinely has less — a button caption that is nothing but the
 * preposition and the value ("ל-30 שניות") — and it is named here rather
 * than the rule being loosened for everybody. Anything matched by it is a
 * node that begins with "ל-", and the value inside is translated on its own.
 */
export const PH_THIN_OK: readonly string[] = ['ל-§'];

