  'מצב בדיקה פעיל — אפשר לבחור קבוצה אחת בלבד. כדי לכבות: §.': 'Тестовый режим активен — можно выбрать только одну группу. Чтобы отключить: §.',
  'מצב בדיקה פעיל: קבוצה אחת בלבד, עם אישור ידני לפני הפרסום. כדי לכבות: §.': 'Тестовый режим активен: только одна группа, с подтверждением вручную перед публикацией. Чтобы отключить: §.',
  'מצב בדיקה: קבוצה אחת בלבד, עם אישור ידני לפני הפרסום. כדי לכבות: §.': 'Тестовый режим: только одна группа, с подтверждением вручную перед публикацией. Чтобы отключить: §.',
  'מצב הפרסום "§" נשמר לחשבון, אבל לא הצלחתי לסנכרן אותו לסבבים עצמם — סבב עם מרווח איטי יותר ימשיך לפרסם בקצב שלו עד שתיגעו בכרטיס שלו. §': 'Режим публикации "§" сохранён для аккаунта, но синхронизировать его с самими циклами не удалось — цикл с более медленным интервалом продолжит публиковать в своём темпе, пока вы не затронете его карточку. §',
