  'ספירת התור לא מסתדרת: § מתוך § פרסומים שויכו לקטגוריה': 'Подсчёт очереди не сходится: § из § публикаций отнесены к категории',
  'עברו § מההשקה. התור נבנה בתוכנה שעל המחשב — בדקו שהיא פתוחה ומחוברת.': 'С запуска прошло §. Очередь строится в программе на компьютере — проверьте, что она открыта и подключена.',
