  'שעת התחלה: §. פתיחת עריכת התזמון של §': 'Час начала: §. Открытие редактирования расписания §',
  'שפת הגרסה §': 'Язык версии §',
  'תושבי §! § עם הגעה עד הבית — כבר מחר באזור שלכם. התקשרו או כתבו ב-WhatsApp, עונה מהר.': 'Жители §! § с выездом на дом — уже завтра в вашем районе. Позвоните или напишите в WhatsApp, отвечаю быстро.',
  '— אבל הן לא נוספו לחזרה של הסבב, ולכן מחר הוא יחזור לרשימה הקודמת: §': '— но они не добавлены в повтор цикла, поэтому завтра он вернётся к предыдущему списку: §',
  '— שימו לב: המרווח הכללי של החשבון הוא §, ולכן הסבב הזה ייצא בקצב הזה ולא ב-§. כדי להאיץ אותו יש להוריד את המרווח הכללי בהגדרות.': '— обратите внимание: общий интервал аккаунта §, поэтому этот цикл выйдет в этом темпе, а не в §. Чтобы его ускорить, нужно снизить общий интервал в настройках.',
  '✨ § עד הבית — §! ✅ ציוד מקצועי ✅ § ✅ מחיר הוגן וברור מראש השבוע מבצע להזמנה ראשונה. התורים מתמלאים — שריינו מקום עכשיו.': '✨ § с выездом на дом — §! ✅ профессиональное оборудование ✅ § ✅ честная и заранее понятная цена На этой неделе акция на первый заказ. Места заполняются — забронируйте сейчас.',
  '§, כולם ב-§': '§, все в §',
  '§. מה שכבר פורסם נשאר בהיסטוריה, והמונה יתחיל מאפס בפעם הבאה שתפרסמו את הפוסט הזה.': '§. То, что уже опубликовано, остаётся в истории, и счётчик начнётся с нуля в следующий раз, когда вы опубликуете этот пост.',
  '§: Supabase חסמה את הפרויקט כי הוא עבר את מכסת§ החודשית. כל המערכת מושבתת עד שמשדרגים את התוכנית ב-Supabase או עד שהמכסה מתאפסת במחזור החיוב הבא — גם המחשב לא מפרסם בינתיים.': '§: Supabase заблокировал проект, потому что он превысил§ месячную квоту. Вся система отключена, пока не повысят тариф в Supabase или пока квота не обнулится в следующем расчётном периоде — компьютер тем временем тоже не публикует.',
  '§: הגנת ה-CAPTCHA של Supabase דחתה את הבקשה. צריך לכבות או להגדיר אותה נכון בהגדרות הפרויקט.': '§: защита CAPTCHA в Supabase отклонила запрос. Нужно отключить её или настроить правильно в настройках проекта.',
  '§: החשבון הזה מסומן כחסום בהגדרות Supabase (Authentication → Users). צריך לשחרר אותו שם.': '§: этот аккаунт помечен как заблокированный в настройках Supabase (Authentication → Users). Нужно разблокировать его там.',
  '§: הכניסה עם מייל וסיסמה כבויה בהגדרות Supabase (Authentication → Sign In / Providers → Email). צריך להדליק אותה שם.': '§: вход по почте и паролю отключён в настройках Supabase (Authentication → Sign In / Providers → Email). Нужно включить его там.',
  '§: הכתובת שהאתר מוגדר אליה לא ענתה כמו פרויקט Supabase. צריך לבדוק את NEXT_PUBLIC_SUPABASE_URL ב-Vercel.': '§: адрес, на который настроен сайт, ответил не как проект Supabase. Нужно проверить NEXT_PUBLIC_SUPABASE_URL в Vercel.',
  '§: המפתח שהאתר מחזיק ל-Supabase לא נתקבל. צריך לעדכן ב-Vercel את NEXT_PUBLIC_SUPABASE_ANON_KEY מהמפתח שב-Supabase → Settings → API Keys, ואז Redeploy.': '§: ключ, который сайт держит для Supabase, не принят. Нужно обновить в Vercel NEXT_PUBLIC_SUPABASE_ANON_KEY ключом из Supabase → Settings → API Keys, а затем сделать Redeploy.',
  '§: הסתיימה.': '§: завершено.',
  '§: השרת דחה את ההרשאה של האתר. צריך לבדוק את מפתחות Supabase ב-Vercel.': '§: сервер отклонил авторизацию сайта. Нужно проверить ключи Supabase в Vercel.',
  '§: ממתינה — התוכנה במחשב עוד לא לקחה אותה.': '§: ожидает — программа на компьютере её ещё не взяла.',
  '§: ממתינה, והתוכנה במחשב לא פועלת. הפעילו אותה שם כדי שהפעולה תתבצע.': '§: ожидает, а программа на компьютере не работает. Запустите её там, чтобы действие выполнилось.',
  '§: מתבצעת עכשיו.': '§: выполняется сейчас.',
  '§: נכשלה.': '§: не удалось.',
  '§: פתיחת חשבונות חדשים כבויה כרגע בהגדרות. פנו למי שהקים את המערכת.': '§: создание новых аккаунтов сейчас отключено в настройках. Обратитесь к тому, кто настроил систему.',
  '§: קובץ גדול מ-100MB.': '§: файл больше 100MB.',
  '§: שרת ההתחברות של Supabase מחזיר שגיאה. לרוב זה פרויקט שמושהה או שעבר את המכסה. בדקו בלוח הבקרה של Supabase שהפרויקט פעיל, ונסו שוב.': '§: сервер входа Supabase возвращает ошибку. Обычно это приостановленный проект или проект, превысивший квоту. Проверьте в панели Supabase, что проект активен, и попробуйте снова.',
  '§§ לא הצליחו': '§§ не удались',
