  'אותו תוכן כבר פורסם ליעד הזה ב-§ הימים האחרונים.': 'То же содержимое уже публиковалось в эту цель за последние § дней.',
  'אותו תוכן כבר פורסם ליעד הזה לאחרונה — החזרה הבאה בעוד כ-§ שעות.': 'То же содержимое недавно уже публиковалось в эту цель — следующий повтор примерно через § часов.',
  'אי-התאמה בספירת הפרסומים — §': 'Расхождение в подсчёте публикаций — §',
  'אף קבוצה לא נכנסה לתור — לכל § הקבוצות כבר ממתין פרסום מסבב אחר§. §': 'Ни одна группа не вошла в очередь — для всех § групп уже ждёт публикация из другого цикла§. §',
