  'בערך § שעות': 'примерно § часов',
  'בתקרה היומית שהגדרתם (§ פרסומים ליום) נשארו היום §, ובמרווח הזה § מהתור אמורים לצאת היום. מה שמעבר לתקרה יידחה למחר.': 'В дневном пределе, который вы задали (§ публикаций в день), осталось сегодня §, а при этом интервале § из очереди должны выйти сегодня. Всё сверх предела будет отложено на завтра.',
