  'דפים: § §, § §, § §, § §. קבוצות מתפרסמות דרך התוכנה שעל המחשב שלכם — ההתקדמות למטה.': 'Страницы: § §, § §, § §, § §. Группы публикуются через программу на вашем компьютере — прогресс ниже.',
