  'ההתחברות נדחתה והשרת לא אמר למה. § — זאת תקלה בצד השרת. הנה מה שהוא החזיר: §': 'Вход отклонён, и сервер не сказал почему. § — это сбой на стороне сервера. Вот что он вернул: §',
