  '; § לא נוספו ונשארו בתיבה': '; § не добавлены и остались в поле',
  'Supabase חסמה את הפרויקט (§) כי הוא עבר מכסה חודשית (402). זאת הסיבה שאי אפשר להיכנס, והסיסמה שלכם בסדר. צריך להיכנס ללוח הבקרה של Supabase, לראות ב-Reports → Usage איזו מכסה נגמרה, ולשדרג את התוכנית או לחכות למחזור החיוב הבא.': 'Supabase заблокировал проект (§), потому что он превысил месячную квоту (402). Именно поэтому войти нельзя, а ваш пароль в порядке. Нужно зайти в панель Supabase, посмотреть в Reports → Usage, какая квота закончилась, и повысить тариф или дождаться следующего расчётного периода.',
