type Compiled = { re: RegExp; out: string };

let compiled: Compiled[] | null = null;
let anchorRe: RegExp | null = null;

function esc(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/** The longest run of literal text in a pattern — what identifies it cheaply. */
function longestLiteral(pattern: string): string {
  let best = '';
  for (const part of pattern.split(PH)) if (part.length > best.length) best = part;
  return best;
}

function compile(): Compiled[] {
  if (compiled) return compiled;
  const rows = Object.entries(RU_PAT)
    /* Longest literal text first: the most specific shape wins a tie. */
    .sort((a, b) => b[0].replace(/§/g, '').length - a[0].replace(/§/g, '').length);
  compiled = rows.map(([he, ru]) => ({
    re: new RegExp('^' + he.split(PH).map(esc).join('([\\s\\S]*?)') + '$'),
    out: ru,
  }));
  const anchors = [...new Set(rows.map(([he]) => longestLiteral(he)).filter((a) => a.trim().length >= 1))];
  anchorRe = anchors.length ? new RegExp(anchors.map(esc).join('|')) : null;
  return compiled;
}

/*
 * THE VALUE INSIDE A PATTERN CAN ITSELF BE A SENTENCE WE KNOW.
 *
 *     `${counted(...)} ל${movedTo ?? 'שעות החדשות'}`
 *
 * The outer shape is a pattern; what lands in the slot is sometimes a group
 * name — the customer's own words, which must be left exactly alone — and
 * sometimes a phrase of ours that has its own translation. So each captured
 * value is looked up as a sentence and as a pattern, and kept as it is when
 * neither answers. A group called "ניקוי ספות באר שבע" is in no dictionary
 * and comes through untouched; "שעות החדשות" is, and turns Russian.
 *
 * ONE LEVEL ONLY, so a value can never send the matcher round again.
 */
function translateValue(value: string): string {
  const trimmed = value.trim();
  if (!trimmed) return value;
  const exact = RU[trimmed];
  const inner = exact ?? matchPattern(trimmed, false);
  if (inner === null || inner === undefined) return value;
  const pre = /^\s*/.exec(value)?.[0] ?? '';
  const post = /\s*$/.exec(value)?.[0] ?? '';
  return pre + inner + post;
}

/**
 * Runs the patterns over one line of Hebrew. Returns null when none fits, so
 * the caller can fall back to the Hebrew rather than show a half-translation.
 * `deep` translates the captured values too, and is false when this is
 * already running on a captured value.
 */
function matchPattern(hebrew: string, deep: boolean): string | null {
  const rows = compile();
  /* One regex decides whether any pattern is even worth trying. Without this
     a DOM walk would run 400 regexes over every text node on the page. */
  if (!anchorRe || !anchorRe.test(hebrew)) return null;
  for (const { re, out } of rows) {
    const m = re.exec(hebrew);
    if (!m) continue;
    const values = m.slice(1).map((v) => (deep ? translateValue(v) : v));
    let i = 0;
    const filled = out.split(PH).reduce((acc, part, idx) => (idx === 0 ? part : acc + (values[i++] ?? '') + part));
    return filled;
  }
  return null;
}

/** The Hebrew sentence when there is no Russian for it — never an empty slot. */
export function translate(lang: Lang, hebrew: string): string {
  if (lang === 'he') return hebrew;
  const exact = RU[hebrew];
  if (exact !== undefined) return exact;
  return matchPattern(hebrew, true) ?? hebrew;
}

/** Every Hebrew sentence this dictionary can answer. Read by the tests. */
export function translatedKeys(): string[] {
  return Object.keys(RU);
}

/** Every Hebrew pattern this dictionary can answer. Read by the tests. */
export function translatedPatterns(): string[] {
  return Object.keys(RU_PAT);
}

/** The Russian written for one fixed sentence, with no pattern involved. */
export function translatedValue(hebrew: string): string | undefined {
  return RU[hebrew];
}

/** The Russian written for one pattern, slots and all. Read by the tests. */
export function translatedPatternValue(pattern: string): string | undefined {
  return RU_PAT[pattern];
}

/* ─── the store ──────────────────────────────────────────────────────────
 *
 * A module store rather than a React context, for one concrete reason: a
 * provider would have to be mounted in src/app/social/layout.tsx, a file
 * every screen in the app renders through, and this task may not put a new
 * wrapper around all of them. Components subscribe to this instead and
 * nothing above them changes.
 */
let current: Lang = 'he';
let booted = false;
const listeners = new Set<() => void>();

function emit() {
  for (const l of listeners) l();
}

/** Applies the choice to the document, which is what makes Russian read LTR. */
function applyToDocument(lang: Lang) {
  if (typeof document === 'undefined') return;
  document.documentElement.setAttribute('lang', lang);
  document.documentElement.setAttribute('dir', dirOf(lang));
}

export function getLang(): Lang {
  return current;
}

export function setLang(lang: Lang): void {
  if (lang !== 'he' && lang !== 'ru') return;
  current = lang;
  try {
    window.localStorage.setItem(LANG_KEY, lang);
  } catch {
    /* a locked-down browser may refuse storage; the choice still applies to
       this page, it just will not survive a reload. Never a crash. */
  }
  applyToDocument(lang);
  emit();
}

/*
 * READ ONCE, AFTER HYDRATION, ON PURPOSE.
 *
 * The server renders Hebrew because it cannot know the choice. If this store
 * answered "ru" during hydration the markup would not match what the server
 * sent and React would discard it. So the first paint is always Hebrew and
 * the stored choice is applied immediately after — one frame, no mismatch.
 */
export function bootLang(): void {
  if (booted || typeof window === 'undefined') return;
  booted = true;
  let saved: string | null = null;
  try {
    saved = window.localStorage.getItem(LANG_KEY);
  } catch {
    saved = null;
  }
  if (saved === 'ru' || saved === 'he') {
    current = saved;
    applyToDocument(saved);
    emit();
  }
}

function subscribe(fn: () => void) {
  listeners.add(fn);
  return () => {
    listeners.delete(fn);
  };
}

export function useLang(): Lang {
  return useSyncExternalStore(
    subscribe,
    () => current,
    () => 'he' as Lang,
  );
}

/*
 * THE PLAIN FUNCTION, for the 61 screens that simply print sentences.
 *
 * A hook in every one of them would mean inserting a line into 61 component
 * bodies by regex — and a component body is exactly the thing a regex gets
 * wrong. So screens call this, and <LangBoundary> re-keys the app when the
 * language changes, which re-renders them all. The price is that a switch
 * remounts the tree; it is a deliberate, rare action, and the alternative was
 * rewriting 61 files blind.
 *
 * Reactive callers (the sign-in screen) keep useT() and do not need the
 * remount at all.
 */
export function t(hebrew: string): string {
  return translate(current, hebrew);
}

/** `const t = useT()` — then `t('ברוכים הבאים')`. */
export function useT(): (hebrew: string) => string {
  const lang = useLang();
  return useCallback((hebrew: string) => translate(lang, hebrew), [lang]);
}
